"""
    Converts odml style tuples to a parsable string representation.
    Every tuple is represented by brackets '()'. The individual elements of a tuple are
    separated by a semicolon ';'. The individual tuples are separated by a comma ','.
    An odml 3-tuple list of 2 tuples would be serialized to: "[(11;12;13),(21;22;23)]".

    :param odml_tuples: List of odml style tuples.
    :return: string
    """
def odml_tuple_export(odml_tuples: Any) -> object {
    str_tuples = "";
    for val in odml_tuples {
        str_val = ";".join(val);
        if str_tuples {
            str_tuples = "%s,(%s)" % (str_tuples, str_val);
        } else {
            str_tuples = "(%s)" % str_val;
        }
    }
    return ("[%s]" % str_tuples);
}

"""Split volume from journal title

    We need this because sometimes the volume is attached to the journal title
    instead of the volume. In those cases we move it here from the title to the
    volume
    """
def split_volume_from_journal(citation_elements: Any) -> object {
    for el in citation_elements {
        if ((el['type'] == 'JOURNAL') and (';' in el['title'])) {
            (el['title'], series) = el['title'].rsplit(';', 1);
            el['volume'] = series + el['volume'];
        }
    }
    return citation_elements;
}

"""take a string of the form "YYYY-MM-DD" (or "YYYY"), terurn a tuple (year, month, date) of three integers"""
def to_ymd(s: Any) -> object {
    if not s {
        return;
    }
    s = s + '--';
    y = s.split('-')[0];
    m = s.split('-')[1];
    d = s.split('-')[2];
    if y {
        y = int(y);
    } else {
        y = None;
    }
    if m {
        m = int(m);
    } else {
        m = None;
    }
    if d {
        d = int(d);
    } else {
        d = None;
    }
    return (y, m, d);
}

